const badges = [Badge(100, "Erste Schritte", "Первые шаги", "🌱", [col(0xFFBBF7D0), col(0xFF16A34A)], col(0xFF15803D)), Badge(250, "Wortsammler", "Собиратель слов", "📖", [col(0xFF99F6E4), col(0xFF0D9488)], col(0xFF0F766E)), Badge(500, "Bronze-Lerner", "Бронзовый ученик", "⭐", [col(0xFFFCD9B0), col(0xFFB45309)], col(0xFF92400E)), Badge(1000, "Silber-Sprecher", "Серебряный оратор", "🗣️", [col(0xFFF8FAFC), col(0xFF94A3B8)], col(0xFF475569)), Badge(1500, "Grammatik-Fuchs", "Лис грамматики", "🦊", [col(0xFFFED7AA), col(0xFFEA580C)], col(0xFFC2410C)), Badge(2500, "Gold-Meister", "Золотой мастер", "✨", [col(0xFFFEF3C7), col(0xFFD97706)], col(0xFFB91C1C)), Badge(4000, "Satzbau-Architekt", "Архитектор фраз", "🏛️", [col(0xFFDDD6FE), col(0xFF7C3AED)], col(0xFF5B21B6)), Badge(6000, "Diamant-Kopf", "Бриллиантовый ум", "💎", [col(0xFFCFFAFE), col(0xFF0891B2)], col(0xFF1E40AF)), Badge(8500, "Sprachrakete", "Языковая ракета", "🚀", [col(0xFFFBCFE8), col(0xFFDB2777)], col(0xFF9D174D)), Badge(12000, "Kronenträger", "Носитель короны", "👑", [col(0xFFFEF9C3), col(0xFFCA8A04)], col(0xFF7C2D12)), Badge(16000, "Sternenkenner", "Знаток звёзд", "🌟", [col(0xFFA5B4FC), col(0xFF312E81)], col(0xFF1E1B4B)), Badge(20000, "Deutsch-Legende", "Легенда немецкого", "🏆", [col(0xFFF472B6), col(0xFFA78BFA), col(0xFF60A5FA), col(0xFF34D399)], col(0xFF111827)), Badge(26000, "Wortakrobat", "Акробат слов", "🤸", [col(0xFFFDE68A), col(0xFFF97316)], col(0xFF9A3412)), Badge(33000, "Grammatik-Magier", "Маг грамматики", "🧙", [col(0xFFC4B5FD), col(0xFF4C1D95)], col(0xFF2E1065)), Badge(41000, "Sprachkapitän", "Капитан языка", "⚓", [col(0xFFBAE6FD), col(0xFF0369A1)], col(0xFF0C4A6E)), Badge(50000, "Goldene Feder", "Золотое перо", "🪶", [col(0xFFFEF08A), col(0xFFB45309)], col(0xFF78350F)), Badge(61000, "Kulturbotschafter", "Посол культуры", "🌍", [col(0xFFA7F3D0), col(0xFF047857)], col(0xFF064E3B)), Badge(74000, "Sprachvirtuose", "Языковой виртуоз", "🎻", [col(0xFFFECACA), col(0xFFB91C1C)], col(0xFF7F1D1D)), Badge(88000, "Dichter und Denker", "Поэт и мыслитель", "📜", [col(0xFFE7E5E4), col(0xFF57534E)], col(0xFF292524)), Badge(100000, "Großmeister", "Гроссмейстер", "🐉", [col(0xFFFDE047), col(0xFFF472B6), col(0xFF8B5CF6), col(0xFF06B6D4)], col(0xFF020617))];
