// ===== Rules.kt =====
const rules = new Map([["sein", Bi("„sein“ ist unregelmäßig: ich bin, du bist, er/sie/es ist, wir sind, ihr seid, sie/Sie sind.", "Глагол «sein» (быть) неправильный, его формы надо выучить наизусть: ich bin, du bist, er/sie/es ist, wir sind, ihr seid, sie/Sie sind.")], ["haben", Bi("„haben“: ich habe, du hast, er/sie/es hat, wir haben, ihr habt, sie/Sie haben.", "Глагол «haben» (иметь) спрягается так: ich habe, du hast, er/sie/es hat, wir haben, ihr habt, sie/Sie haben.")], ["nom", Bi("Das Subjekt steht im Nominativ (Frage: Wer? Was?): der, die, das, ein, eine.", "Подлежащее всегда стоит в именительном падеже (Nominativ) и отвечает на вопрос «кто? что?»: der, die, das, ein, eine.")], ["akk", Bi("Das direkte Objekt steht im Akkusativ (Wen? Was?). Nur maskulin ändert sich: der → den, ein → einen, kein → keinen. Feminin, Neutrum und Plural bleiben gleich.", "Прямое дополнение ставится в винительный падеж (Akkusativ, вопрос «кого? что?»). Артикль меняется только в мужском роде: der → den, ein → einen, kein → keinen. В женском и среднем роде и во множественном числе всё остаётся как было.")], ["dat", Bi("Dativ (Wem?): der → dem, die → der, das → dem, Plural die → den (+ -n am Nomen). ein → einem, eine → einer.", "Дательный падеж (Dativ) отвечает на вопрос «кому?»: der → dem, die → der, das → dem, во множественном числе die → den, а к существительному добавляется -n. Неопределённый артикль: ein → einem, eine → einer.")], ["dat_verb", Bi("Einige Verben verlangen den Dativ: helfen, danken, gefallen, gehören, antworten, gratulieren, schmecken, passen.", "После некоторых глаголов нужен дательный падеж: helfen (помогать), danken (благодарить), gefallen (нравиться), gehören (принадлежать), antworten (отвечать), gratulieren (поздравлять), schmecken (быть по вкусу), passen (подходить). Их лучше запомнить списком.")], ["dat_prep", Bi("aus, bei, mit, nach, seit, von, zu stehen immer mit Dativ. Kurzformen: zum = zu dem, zur = zu der, beim = bei dem, vom = von dem.", "После предлогов aus, bei, mit, nach, seit, von, zu всегда идёт дательный падеж. Предлог часто сливается с артиклем: zum = zu dem, zur = zu der, beim = bei dem, vom = von dem.")], ["akk_prep", Bi("durch, für, gegen, ohne, um stehen immer mit Akkusativ.", "После предлогов durch (через), für (для), gegen (против), ohne (без), um (вокруг; в — о времени) всегда идёт винительный падеж.")], ["wechsel_wo", Bi("Wechselpräpositionen (in, an, auf, über, unter, vor, hinter, neben, zwischen): Wo? (Ort, keine Bewegung) → Dativ. im = in dem, am = an dem.", "Предлоги in, an, auf, über, unter, vor, hinter, neben, zwischen могут требовать двух падежей. Если вопрос «где?» (место, никакого движения), нужен дательный падеж. Сокращения: im = in dem, am = an dem.")], ["wechsel_wohin", Bi("Wechselpräpositionen: Wohin? (Richtung, Bewegung) → Akkusativ. ins = in das, ans = an das.", "Те же предлоги (in, an, auf …) с вопросом «куда?» (направление, движение) требуют винительного падежа. Сокращения: ins = in das, ans = an das.")], ["stellen_stehen", Bi("Positionsverben: stellen/legen/setzen/hängen (Wohin? + Akkusativ, Handlung) — stehen/liegen/sitzen/hängen (Wo? + Dativ, Zustand).", "Глаголы действия stellen/legen/setzen/hängen (поставить, положить, посадить, повесить) отвечают на вопрос «куда?» и требуют Akkusativ. Глаголы состояния stehen/liegen/sitzen/hängen (стоять, лежать, сидеть, висеть) отвечают на вопрос «где?» и требуют Dativ.")], ["kein_nicht", Bi("„kein“ verneint Nomen mit unbestimmtem Artikel oder ohne Artikel (Ich habe keine Zeit). „nicht“ verneint Verben, Adjektive, Adverbien und Nomen mit bestimmtem Artikel.", "«kein» ставится перед существительным с неопределённым артиклем или без артикля: Ich habe keine Zeit (у меня нет времени). «nicht» отрицает глаголы, прилагательные, наречия и существительные с определённым артиклем.")], ["poss", Bi("Possessivartikel: mein, dein, sein (er/es), ihr (sie), unser, euer, ihr (sie Pl.), Ihr (Sie). Endungen wie beim unbestimmten Artikel: mein Vater, meine Mutter, meinen Vater (Akk).", "Притяжательные слова: mein (мой), dein (твой), sein (его), ihr (её), unser (наш), euer (ваш), ihr (их), Ihr (Ваш). Окончания у них такие же, как у неопределённого артикля: mein Vater, meine Mutter, meinen Vater (Akk).")], ["wfrage", Bi("Fragewörter: wer, was, wo, wohin, woher, wann, wie, warum, wie viel. Das Verb steht direkt nach dem Fragewort.", "Вопросительные слова: wer (кто), was (что), wo (где), wohin (куда), woher (откуда), wann (когда), wie (как), warum (почему), wie viel (сколько). Сразу после вопросительного слова идёт глагол.")], ["wer_wen_wem", Bi("wer = Nominativ (Subjekt), wen = Akkusativ, wem = Dativ, wessen = Genitiv.", "wer — кто (Nominativ), wen — кого (Akkusativ), wem — кому (Dativ), wessen — чей (Genitiv).")], ["modal", Bi("Modalverben (können, müssen, wollen, dürfen, sollen, mögen): ich und er/sie/es haben keine Endung (ich kann, er muss). Der Infinitiv steht am Satzende.", "Модальные глаголы (können, müssen, wollen, dürfen, sollen, mögen) у ich и er/sie/es не имеют окончания: ich kann, er muss. Второй глагол стоит в конце предложения в инфинитиве.")], ["modal_bed", Bi("Bedeutung: können = Fähigkeit/Möglichkeit, müssen = Notwendigkeit, dürfen = Erlaubnis, wollen = eigener Wunsch, sollen = Auftrag eines anderen, möchten = höflicher Wunsch.", "Что значат модальные глаголы: können — мочь, уметь; müssen — быть обязанным, «надо»; dürfen — «можно», есть разрешение; wollen — хотеть (сам); sollen — «должен», потому что так сказал кто-то другой; möchten — «хотел бы» (вежливо).")], ["trennbar", Bi("Trennbare Verben (aufstehen, einkaufen, anrufen, fernsehen …): Im Hauptsatz steht das Präfix am Satzende: Ich stehe um 7 Uhr auf.", "У глаголов с отделяемой приставкой (aufstehen, einkaufen, anrufen, fernsehen …) в главном предложении приставка отрывается и уходит в самый конец: Ich stehe um 7 Uhr auf.")], ["v2", Bi("Im Aussagesatz steht das konjugierte Verb immer an Position 2. Steht etwas anderes (Zeit, Ort) auf Position 1, kommt das Subjekt direkt nach dem Verb.", "В обычном (повествовательном) предложении спрягаемый глагол всегда стоит на втором месте. Если первое место занято чем-то другим (временем, местом), подлежащее ставится сразу после глагола.")], ["vfrage", Bi("Ja/Nein-Fragen beginnen mit dem konjugierten Verb: Kommst du heute?", "Вопрос, на который отвечают «да» или «нет», начинается со спрягаемого глагола: Kommst du heute?")], ["satzklammer", Bi("Satzklammer: Das konjugierte Verb steht auf Position 2, der zweite Verbteil (Infinitiv, Partizip, Präfix) am Ende.", "Немецкое сказуемое образует «рамку»: спрягаемый глагол стоит на втором месте, а его вторая часть (инфинитив, причастие или приставка) — в самом конце предложения.")], ["nebensatz", Bi("In Nebensätzen (mit weil, dass, wenn, ob, obwohl, als, damit …) steht das konjugierte Verb am Ende. Vor dem Nebensatz steht ein Komma.", "В придаточном предложении (после weil, dass, wenn, ob, obwohl, als, damit …) спрягаемый глагол уходит в самый конец. Придаточное всегда отделяется запятой.")], ["nebensatz_vorn", Bi("Steht der Nebensatz vorn, zählt er als Position 1 — danach folgt sofort das Verb des Hauptsatzes: Wenn es regnet, bleibe ich zu Hause.", "Если придаточное стоит в начале, оно целиком занимает первое место. Поэтому сразу за ним идёт глагол главного предложения: Wenn es regnet, bleibe ich zu Hause.")], ["konnektor_adv", Bi("deshalb, trotzdem, dann, danach, sonst sind Adverbien: Sie stehen auf Position 1, danach kommt sofort das Verb, dann das Subjekt.", "deshalb (поэтому), trotzdem (тем не менее), dann (потом), danach (после этого), sonst (иначе) — это наречия. Они сами занимают первое место, поэтому за ними сразу идёт глагол, а потом подлежащее.")], ["konnektor_0", Bi("und, aber, oder, denn, sondern stehen auf Position 0: Die Wortstellung danach ändert sich nicht.", "Союзы und (и), aber (но), oder (или), denn (потому что), sondern (а) не занимают места в предложении («нулевая позиция»), поэтому порядок слов после них обычный.")], ["perfekt_haben", Bi("Perfekt = haben/sein + Partizip II. Die meisten Verben (besonders mit Akkusativobjekt) bilden das Perfekt mit „haben“.", "Перфект образуется так: haben или sein + Partizip II. Большинство глаголов, особенно те, у которых есть прямое дополнение, берут «haben».")], ["perfekt_sein", Bi("Perfekt mit „sein“: Verben der Bewegung von A nach B (gehen, fahren, kommen, fliegen) und der Zustandsänderung (aufstehen, einschlafen, werden) sowie sein, bleiben, passieren.", "С «sein» перфект образуют глаголы перемещения из одного места в другое (gehen, fahren, kommen, fliegen) и глаголы, обозначающие переход в новое состояние (aufstehen, einschlafen, werden). Кроме того: sein, bleiben, passieren.")], ["partizip", Bi("Partizip II: regelmäßig ge-…-t (gemacht), unregelmäßig ge-…-en (gesehen). Trennbare Verben: auf-ge-standen. Ohne ge-: Verben auf -ieren (studiert) und mit be-, ver-, er-, ent-, zer- (besucht, verstanden).", "Как строится Partizip II: у правильных глаголов ge-…-t (gemacht), у неправильных ge-…-en (gesehen). У глаголов с отделяемой приставкой ge- стоит в середине: auf-ge-standen. Без ge-: глаголы на -ieren (studiert) и с приставками be-, ver-, er-, ent-, zer- (besucht, verstanden).")], ["praet", Bi("Präteritum von sein, haben und Modalverben benutzt man auch im Gespräch: war, hatte, konnte, musste, wollte, durfte, sollte.", "У sein, haben и модальных глаголов претерит звучит и в обычном разговоре: war, hatte, konnte, musste, wollte, durfte, sollte.")], ["praet_stark", Bi("Präteritum wird vor allem in Erzählungen und Texten benutzt. Starke Verben ändern den Vokal: gehen → ging, kommen → kam, sehen → sah, finden → fand. Regelmäßige: machen → machte.", "Претерит встречается в основном в рассказах и письменных текстах. Сильные глаголы меняют гласную корня: gehen → ging, kommen → kam, sehen → sah, finden → fand. Правильные просто получают -te: machen → machte.")], ["pqp", Bi("Plusquamperfekt = hatte/war + Partizip II: eine Handlung vor einer anderen in der Vergangenheit (oft mit „nachdem“).", "Плюсквамперфект (hatte/war + Partizip II) показывает, что одно действие в прошлом случилось раньше другого. Часто стоит после «nachdem» (после того как).")], ["futur", Bi("Futur I = werden + Infinitiv am Ende: Ich werde morgen arbeiten. Es drückt Zukunft, Pläne oder Vermutungen aus.", "Futur I = werden + инфинитив в конце предложения: Ich werde morgen arbeiten. Так говорят о будущем, о планах или о предположениях.")], ["komparativ", Bi("Komparativ: Adjektiv + -er + als (schneller als). Superlativ: am …-sten (am schnellsten). Unregelmäßig: gut – besser – am besten, viel – mehr – am meisten, gern – lieber – am liebsten. Oft Umlaut: alt – älter.", "Сравнительная степень: прилагательное + -er, дальше als (schneller als — быстрее, чем). Превосходная: am …-sten (am schnellsten). Исключения: gut – besser – am besten, viel – mehr – am meisten, gern – lieber – am liebsten. Часто появляется умлаут: alt – älter.")], ["so_wie", Bi("Gleichheit: so + Adjektiv + wie (so groß wie). Ungleichheit: Komparativ + als (größer als).", "Если предметы одинаковы: so + прилагательное + wie (so groß wie — такой же большой, как). Если разные: сравнительная степень + als (größer als — больше, чем).")], ["reflexiv", Bi("Reflexivpronomen im Akkusativ: mich, dich, sich, uns, euch, sich. Mit einem weiteren Akkusativobjekt im Dativ: Ich wasche mir die Hände.", "Возвратное местоимение («себя», «-ся») обычно стоит в винительном падеже: mich, dich, sich, uns, euch, sich. Если в предложении есть ещё одно прямое дополнение, местоимение переходит в дательный: Ich wasche mir die Hände (я мою руки).")], ["pron_akk", Bi("Personalpronomen im Akkusativ: mich, dich, ihn, sie, es, uns, euch, sie, Sie.", "Личные местоимения в винительном падеже: mich (меня), dich (тебя), ihn (его), sie (её), es (его — о среднем роде), uns (нас), euch (вас), sie (их), Sie (Вас).")], ["pron_dat", Bi("Personalpronomen im Dativ: mir, dir, ihm, ihr, ihm, uns, euch, ihnen, Ihnen.", "Личные местоимения в дательном падеже: mir (мне), dir (тебе), ihm (ему), ihr (ей), uns (нам), euch (вам), ihnen (им), Ihnen (Вам).")], ["imperativ", Bi("Imperativ: du-Form = Verbstamm ohne -st und ohne du (Komm! Nimm! Lies!), ihr-Form wie Präsens ohne ihr (Kommt!), Sie-Form: Kommen Sie!", "Повелительное наклонение. Для du: основа глагола без -st и без самого du (Komm! Nimm! Lies!). Для ihr: форма настоящего времени без ihr (Kommt!). Вежливо: Kommen Sie!")], ["adj_def", Bi("Adjektiv nach bestimmtem Artikel: Nominativ Singular immer -e (der große Mann, die/das …), Akkusativ feminin/neutrum -e; alle anderen Formen (Akk. mask., Dativ, Plural) -en.", "Прилагательное после определённого артикля: в Nominativ единственного числа окончание всегда -e (der große Mann), в Akkusativ женского и среднего рода тоже -e. Во всех остальных случаях (Akkusativ мужского рода, Dativ, множественное число) — -en.")], ["adj_indef", Bi("Adjektiv nach unbestimmtem Artikel: ein großer Mann, eine große Frau, ein großes Haus; Akkusativ: einen großen Mann; Dativ immer -en.", "Прилагательное после неопределённого артикля «показывает» род само: ein großer Mann, eine große Frau, ein großes Haus. В Akkusativ: einen großen Mann. В Dativ окончание всегда -en.")], ["adj_null", Bi("Adjektiv ohne Artikel übernimmt die Endung des Artikels: kalter Kaffee (der), frische Milch (die), kaltes Wasser (das), mit kaltem Wasser (dem).", "Если артикля нет, прилагательное берёт на себя его окончание: kalter Kaffee (der), frische Milch (die), kaltes Wasser (das), mit kaltem Wasser (dem).")], ["relativ", Bi("Relativpronomen: Genus und Zahl kommen vom Bezugswort, der Kasus aus dem Relativsatz. Dativ Plural: denen. Das Verb steht am Ende.", "Относительное местоимение («который»): род и число берутся от слова, к которому оно относится, а падеж — от его роли в придаточном. В Dativ множественного числа — denen. Глагол стоит в конце.")], ["zu_inf", Bi("zu + Infinitiv nach Verben wie versuchen, vergessen, anfangen, aufhören, hoffen und nach „Es ist wichtig/schön …“, „Lust/Zeit haben“. Nicht nach Modalverben! Trennbar: anzurufen.", "zu + инфинитив ставится после глаголов versuchen (пытаться), vergessen (забыть), anfangen (начинать), aufhören (переставать), hoffen (надеяться), а также после «Es ist wichtig/schön …» и «Lust/Zeit haben». После модальных глаголов zu не нужно! У глаголов с отделяемой приставкой zu встаёт внутрь: anzurufen.")], ["um_zu", Bi("Ziel/Zweck: um … zu + Infinitiv (gleiches Subjekt), damit + Nebensatz (verschiedene Subjekte).", "Цель («чтобы») выражается двумя способами: um … zu + инфинитив, если подлежащее одно и то же, и damit + придаточное, если подлежащие разные.")], ["wenn_als", Bi("als = einmaliges Ereignis in der Vergangenheit. wenn = wiederholt (immer wenn) oder Gegenwart/Zukunft und Bedingung.", "Оба слова переводятся «когда», но: als — одно событие в прошлом, которое случилось один раз. wenn — то, что повторялось («каждый раз, когда»), настоящее или будущее, а также условие («если»).")], ["ob_dass", Bi("„dass“ leitet eine Aussage ein, „ob“ eine indirekte Ja/Nein-Frage (Ich weiß nicht, ob …).", "«dass» (что) вводит утверждение. «ob» (ли) вводит косвенный вопрос, на который можно ответить «да» или «нет»: Ich weiß nicht, ob er kommt — я не знаю, придёт ли он.")], ["weil_denn", Bi("weil = Nebensatz, Verb am Ende. denn = Hauptsatz, Verb auf Position 2. Beide nennen einen Grund. deshalb = Folge.", "И weil, и denn значат «потому что», но порядок слов разный: после weil — придаточное, глагол в конце; после denn — обычное предложение, глагол на втором месте. А deshalb (поэтому) называет следствие.")], ["obwohl", Bi("obwohl + Nebensatz (Verb am Ende) = Gegensatz. trotzdem = Adverb im Hauptsatz (Verb folgt direkt).", "obwohl (хотя) вводит придаточное с глаголом в конце. trotzdem (всё равно, тем не менее) — наречие в главном предложении, сразу за ним идёт глагол.")], ["passiv", Bi("Passiv = werden + Partizip II. Präsens: wird gebaut, Präteritum: wurde gebaut, Perfekt: ist gebaut worden. Der Handelnde mit „von“ + Dativ.", "Пассив = werden + Partizip II. Настоящее время: wird gebaut, претерит: wurde gebaut, перфект: ist gebaut worden. Того, кто совершает действие, вводят через «von» + Dativ.")], ["konj2", Bi("Konjunktiv II für Wünsche, irreale Bedingungen und höfliche Bitten: würde + Infinitiv, wäre, hätte, könnte, müsste. Vergangenheit: hätte/wäre + Partizip II.", "Konjunktiv II — это немецкое сослагательное наклонение («бы»). Он нужен для желаний, нереальных условий и вежливых просьб: würde + инфинитив, wäre, hätte, könnte, müsste. О прошлом: hätte/wäre + Partizip II.")], ["konj1", Bi("Konjunktiv I in der indirekten Rede (Nachrichten): er sei, er habe, er komme, er könne. Ist die Form gleich wie der Indikativ, nimmt man Konjunktiv II.", "Konjunktiv I используют в косвенной речи, особенно в новостях: er sei, er habe, er komme, er könne. Если форма совпадает с обычной (изъявительной), вместо неё берут Konjunktiv II.")], ["genitiv", Bi("Genitiv (Wessen?): des Mannes, des Kindes (mask./neutr. + -(e)s), der Frau, der Kinder. Präpositionen mit Genitiv: wegen, während, trotz, statt, innerhalb.", "Родительный падеж (Genitiv) отвечает на вопрос «чей?»: des Mannes, des Kindes (мужской и средний род получают -(e)s), der Frau, der Kinder. Предлоги с Genitiv: wegen (из-за), während (во время), trotz (несмотря на), statt (вместо), innerhalb (в течение).")], ["n_dekl", Bi("n-Deklination: Einige maskuline Nomen (Student, Kollege, Junge, Herr, Mensch, Nachbar, Name) bekommen außer im Nominativ Singular immer -(e)n: den Studenten, dem Kollegen.", "n-склонение: несколько существительных мужского рода (Student, Kollege, Junge, Herr, Mensch, Nachbar, Name) получают -(e)n во всех формах, кроме Nominativ единственного числа: den Studenten, dem Kollegen.")], ["praep_verb", Bi("Verben mit fester Präposition muss man mitlernen: warten auf + Akk, sich freuen auf (Zukunft) / über (Gegenwart) + Akk, denken an + Akk, sich interessieren für + Akk, Angst haben vor + Dat, träumen von + Dat, teilnehmen an + Dat.", "У многих глаголов свой постоянный предлог — его учат вместе с глаголом: warten auf + Akk (ждать), sich freuen auf + Akk (радоваться будущему) / über + Akk (радоваться тому, что уже есть), denken an + Akk (думать о), sich interessieren für + Akk (интересоваться), Angst haben vor + Dat (бояться), träumen von + Dat (мечтать о), teilnehmen an + Dat (участвовать в).")], ["da_wo", Bi("Bei Sachen: da- / wo- + Präposition (darauf, worauf, daran, woran; mit Vokal: dar-/wor-). Bei Personen: Präposition + Pronomen (auf ihn, auf wen).", "Когда речь о предметах, предлог сливается с da- или wo-: darauf, worauf, daran, woran (перед гласной — dar-/wor-). Когда речь о людях: предлог + местоимение (auf ihn, auf wen).")], ["je_desto", Bi("je + Komparativ (Nebensatz, Verb am Ende), desto/umso + Komparativ (Verb folgt direkt): Je mehr du übst, desto besser sprichst du.", "«Чем …, тем …» по-немецки: je + сравнительная степень (придаточное, глагол в конце), затем desto/umso + сравнительная степень (глагол сразу после): Je mehr du übst, desto besser sprichst du — чем больше ты занимаешься, тем лучше говоришь.")], ["zweiteilig", Bi("Zweiteilige Konnektoren: sowohl … als auch, weder … noch, entweder … oder, nicht nur … sondern auch, zwar … aber.", "Парные союзы: sowohl … als auch (как …, так и), weder … noch (ни …, ни), entweder … oder (или …, или), nicht nur … sondern auch (не только …, но и), zwar … aber (хотя и …, но).")], ["partizip_attr", Bi("Partizip I (Infinitiv + d) = aktiv, gleichzeitig: das weinende Kind. Partizip II = passiv/abgeschlossen: das reparierte Auto. Als Attribut bekommen sie Adjektivendungen.", "Partizip I (инфинитив + d) описывает того, кто сам что-то делает прямо сейчас: das weinende Kind (плачущий ребёнок). Partizip II описывает то, с чем что-то сделали: das reparierte Auto (отремонтированная машина). Перед существительным оба получают окончания прилагательных.")], ["lassen", Bi("lassen + Infinitiv: etwas nicht selbst machen, sondern machen lassen (Ich lasse mein Auto reparieren). Perfekt: Ich habe es reparieren lassen.", "lassen + инфинитив значит, что человек делает что-то не сам, а поручает другому: Ich lasse mein Auto reparieren — я отдаю машину в ремонт. В перфекте: Ich habe es reparieren lassen.")], ["seit", Bi("seit + Dativ für eine Handlung, die noch andauert — im Deutschen steht dann das Präsens: Ich wohne seit zwei Jahren hier.", "seit + Dativ — для того, что началось в прошлом и продолжается до сих пор. В немецком тогда ставится настоящее время: Ich wohne seit zwei Jahren hier — я живу здесь уже два года.")], ["zeit_prep", Bi("Zeitangaben: um + Uhrzeit (um 8 Uhr), am + Tag/Datum/Tageszeit (am Montag, am Abend; aber: in der Nacht), im + Monat/Jahreszeit (im Mai, im Winter).", "Как сказать, когда: um + время по часам (um 8 Uhr), am + день, дата или часть суток (am Montag, am Abend; но: in der Nacht), im + месяц или время года (im Mai, im Winter).")], ["ort_prep", Bi("Richtung: nach + Städte/Länder ohne Artikel (nach Berlin), nach Hause; in + Länder mit Artikel (in die Schweiz); zu + Personen/Orten (zum Arzt). Ort: in Berlin, zu Hause, beim Arzt.", "Куда: nach + город или страна без артикля (nach Berlin), а также nach Hause (домой); in + страна с артиклем (in die Schweiz); zu + человек или учреждение (zum Arzt — к врачу). Где: in Berlin, zu Hause (дома), beim Arzt (у врача).")], ["es_gibt", Bi("„es gibt“ + Akkusativ = es existiert, es ist vorhanden: Es gibt einen Park.", "«es gibt» + Akkusativ значит «есть, имеется»: Es gibt einen Park — здесь есть парк.")], ["gern", Bi("gern + Verb = etwas gern tun. mögen + Nomen (Ich mag Kaffee). möchten = höflicher Wunsch.", "gern + глагол — любить что-то делать (Ich spiele gern). mögen + существительное — любить что-то (Ich mag Kaffee — я люблю кофе). möchten — вежливое «хотел бы».")], ["welch", Bi("welcher/welche/welches dekliniert man wie der/die/das: Welchen Film (Akk mask.) siehst du?", "welcher/welche/welches (какой, который) склоняется так же, как der/die/das: Welchen Film siehst du? (Akkusativ мужского рода).")], ["werden", Bi("„werden“: ich werde, du wirst, er wird, wir werden, ihr werdet, sie werden. Perfekt: ist geworden.", "Глагол «werden» (становиться) спрягается так: ich werde, du wirst, er wird, wir werden, ihr werdet, sie werden. Перфект: ist geworden.")], ["indef", Bi("Unbestimmte Pronomen: man (Menschen allgemein, + er-Form), jemand, niemand, etwas, nichts, alle.", "Неопределённые местоимения: man (люди вообще; глагол стоит в форме er: man sagt — говорят), jemand (кто-то), niemand (никто), etwas (что-то), nichts (ничего), alle (все).")], ["plural_dat", Bi("Im Dativ Plural bekommt das Nomen ein -n (außer bei -s und wenn schon -n da ist): mit den Kindern.", "В дательном падеже множественного числа к существительному добавляется -n: mit den Kindern. Исключение — слова на -s и те, что уже оканчиваются на -n.")], ["nominal", Bi("Nominalisierung (typisch für Schrifttext): beim + Infinitiv (beim Essen = während man isst), nach dem / vor dem + Nomen.", "В письменной речи вместо придаточного часто используют существительное: beim + инфинитив (beim Essen — во время еды, то есть пока едят), nach dem / vor dem + существительное (nach dem Essen — после еды).")], ["ohne_statt", Bi("ohne … zu / statt … zu + Infinitiv (gleiches Subjekt): Er ging, ohne sich zu verabschieden.", "ohne … zu (не делая чего-то) и statt … zu (вместо того чтобы) + инфинитив, если подлежащее одно: Er ging, ohne sich zu verabschieden — он ушёл не попрощавшись.")], ["brauchen_zu", Bi("nicht brauchen + zu + Infinitiv = nicht müssen: Du brauchst nicht zu kommen.", "nicht brauchen + zu + инфинитив значит «не нужно, не обязательно» (то же, что nicht müssen): Du brauchst nicht zu kommen — тебе не нужно приходить.")], ["doch", Bi("Auf eine negative Frage antwortet man positiv mit „doch“, negativ mit „nein“.", "Если вопрос задан с отрицанием, а вы хотите возразить и ответить утвердительно, говорят «doch» («нет, …!», «да нет же»). Согласиться с отрицанием — «nein»: Kommst du nicht? — Doch! (Приду!) / Nein. (Не приду.)")], ["ordinal", Bi("Ordnungszahlen: der erste, zweite, dritte, siebte, achte; ab 20 mit -ste (der zwanzigste). Sie bekommen Adjektivendungen: am ersten Mai, im dritten Stock.", "Порядковые числительные: der erste, zweite, dritte, siebte, achte; начиная с 20 — с окончанием -ste (der zwanzigste). Они изменяются как прилагательные: am ersten Mai (первого мая), im dritten Stock (на третьем этаже).")], ["viel", Bi("viel/wenig + Singular (Unzählbares, ohne Endung): viel Zeit, wenig Geld. viele/wenige + Plural: viele Freunde, wenige Leute.", "viel/wenig ставят перед тем, что нельзя посчитать (без окончания): viel Zeit, wenig Geld. viele/wenige — перед множественным числом: viele Freunde, wenige Leute.")], ["nicht_pos", Bi("„nicht“ verneint den ganzen Satz und steht dann möglichst weit hinten: nach dem Objekt (Ich verstehe dich nicht), aber vor dem zweiten Verbteil (Ich habe den Film nicht gesehen).", "Если «nicht» отрицает всё предложение, оно стоит как можно дальше к концу: после дополнения (Ich verstehe dich nicht), но перед второй частью сказуемого (Ich habe den Film nicht gesehen).")], ["temporal", Bi("Temporale Nebensätze: bevor (vorher), nachdem (danach, meist mit Plusquamperfekt), während (gleichzeitig), seit/seitdem (von damals bis jetzt), bis (bis zu dem Zeitpunkt). Das Verb steht am Ende.", "Придаточные времени: bevor (прежде чем), nachdem (после того как; обычно с плюсквамперфектом), während (пока, в то время как), seit/seitdem (с тех пор как), bis (пока не, до тех пор пока). Глагол в них стоит в конце.")], ["modal_vergangenheit", Bi("Modalverben in der Vergangenheit: meist Präteritum ohne Umlaut — konnte, musste, durfte, wollte, sollte (ich/er ohne Endung). Perfekt mit zweitem Verb: haben + zwei Infinitive am Ende (Ich habe arbeiten müssen); im Nebensatz steht „haben“ davor (…, dass er nicht hat kommen können). Ohne zweites Verb: Partizip gekonnt, gemusst, gewollt.", "О прошлом модальные глаголы чаще всего говорят в претерите, и умлаут при этом исчезает: konnte, musste, durfte, wollte, sollte (у ich и er окончания нет). Перфект со вторым глаголом: haben + два инфинитива в конце (Ich habe arbeiten müssen); в придаточном haben стоит перед ними (…, dass er nicht hat kommen können). Без второго глагола используют причастие: gekonnt, gemusst, gewollt.")], ["uhrzeit", Bi("Uhrzeit: Viertel nach (+15 Min.), Viertel vor (−15 Min.), halb + nächste Stunde: halb neun = 8:30.", "Время по часам: Viertel nach — четверть (+15 минут), Viertel vor — без четверти, halb + следующий час: halb neun = 8:30 (половина девятого).")]]);
